# Generate logo.svg
logo_svg = """<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100" viewBox="0 0 100 100" fill="none">
  <rect width="100" height="100" rx="24" fill="#0F172A"/>
  <rect x="2" y="2" width="96" height="96" rx="22" stroke="#1E293B" stroke-width="4" fill="none"/>
  <!-- Shield/Vault outline -->
  <path d="M30 30 C30 30, 50 22, 50 22 C50 22, 70 30, 70 30 V55 C70 67, 50 78, 50 78 C50 78, 30 67, 30 55 Z" stroke="#3B82F6" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" fill="#1E293B"/>
  <!-- Keyhole or AI Sparkle -->
  <path d="M50 38 L52 46 L60 48 L52 50 L50 58 L48 50 L40 48 L48 46 Z" fill="#F8FAFC"/>
</svg>
"""

with open("../assets/logo.svg", "w", encoding="utf-8") as f:
    f.write(logo_svg)

# Generate individual icons
for name, path in icons.items():
    svg_content = f"""<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-{name}">
  {path}
</svg>
"""
    with open(f"../assets/icons/{name}.svg", "w", encoding="utf-8") as f:
        f.write(svg_content)

print(f"Generated logo.svg and {len(icons)} icons in assets/icons/!")
